let data=[];const $=id=>document.getElementById(id),n=(r,k)=>Number(r[k]||0),pct=x=>`${(100*n({x},'x')).toFixed(0)}%`,band=x=>x>.70?'High':x>.40?'Medium':'Low';
function csv(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){let c=text[i],next=text[i+1];if(c==='"'&&q&&next==='"'){cell+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&next==='\n')i++;row.push(cell);if(row.some(x=>x))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}const [h,...b]=rows;return b.map(r=>Object.fromEntries(h.map((x,i)=>[x.trim(),(r[i]||'').trim()])))}
const badge=(x,c=x)=>`<span class="badge ${String(c).toLowerCase()}">${x}</span>`;function actionReason(r){return r.action_reason||`${r.planner_action} because ${r.risk_band} combined risk and the strongest signal is ${primary(r).label}.`};function primary(r){const a=[['volatility_risk','Requirement volatility'],['resolution_risk','Resolution delay'],['reopen_risk','Reopen']].sort((x,y)=>n(r,y[0])-n(r,x[0]));return{key:a[0][0],label:a[0][1],value:n(r,a[0][0])}}
function factors(r){if(r.top_factors){try{return JSON.parse(r.top_factors)}catch{return r.top_factors.split(';')}}return[`${primary(r).label} is the highest predicted risk signal.`,`Combined risk is ${pct(n(r,'combined_risk'))}.`]}
function points(r){return Number(r.story_points||r.effort_estimate||1)}function recommendedWork(){return data.reduce((s,r)=>s+(r.planner_action==='Include'||r.planner_action==='Monitor'?points(r):r.planner_action==='Split'?points(r)*.5:0),0)}
function overview(){const cap=n({x:$('capacityInput').value},'x'),work=recommendedWork(),high=data.filter(r=>n(r,'combined_risk')>.70).length,mean=data.reduce((s,r)=>s+n(r,'combined_risk'),0)/data.length,score=Math.round(100*(1-(.7*mean+.3*high/data.length))*10)/10;$('recommendedWork').textContent=work.toFixed(1);$('commitmentDetail').textContent=`${work<=cap?'Within':'Over'} the ${cap}-point capacity by ${Math.abs(cap-work).toFixed(1)} points.`;$('healthScore').textContent=score;$('healthBand').textContent=score>=70?'Healthy':score>=45?'At Risk':'Critical';$('healthBar').style.width=`${score}%`;$('highRisk').textContent=high;$('actionDistribution').innerHTML=['Include','Monitor','Split','Defer'].map(a=>`<div class="action-box ${a.toLowerCase()}"><span>${a}</span><strong>${data.filter(r=>r.planner_action===a).length}</strong></div>`).join('')}
function render(){if(!data.length)return;overview();const shown=data.filter(r=>($('bandFilter').value==='All'||r.risk_band===$('bandFilter').value)&&($('actionFilter').value==='All'||r.planner_action===$('actionFilter').value));const sort=$('sortBy').value;shown.sort((a,b)=>sort==='points'?points(b)-points(a):sort==='action'?a.planner_action.localeCompare(b.planner_action):n(b,'combined_risk')-n(a,'combined_risk'));$('rows').innerHTML=shown.length?shown.map(r=>`<tr data-index="${data.indexOf(r)}"><td><strong>${r.issue_key}</strong><div class="summary">${r.summary||'No summary provided'}</div></td><td>${points(r)}</td><td>${pct(n(r,'volatility_risk'))}<br>${badge(band(n(r,'volatility_risk')))}</td><td>${pct(n(r,'resolution_risk'))}<br>${badge(band(n(r,'resolution_risk')))}</td><td>${pct(n(r,'reopen_risk'))}<br>${badge(band(n(r,'reopen_risk')))}</td><td>${badge(r.priority||'—',String(r.priority||'low').toLowerCase())}</td><td>${r.has_dependencies==='1'||r.has_dependencies===true?'Yes':'None flagged'}</td><td>${badge(r.planner_action)}</td></tr>`).join(''):`<tr><td colspan="8" class="empty">No items match these filters.</td></tr>`;document.querySelectorAll('tr[data-index]').forEach(row=>row.onclick=()=>drill(data[row.dataset.index]))}
function drill(r){const rec=r.llm_recommendation,ground=rec?(rec.fallback_used?'Fallback approved strategy used':'Approved strategy IDs verified'):'Not generated';$('detailContent').innerHTML=`<h2>${r.issue_key}</h2><p class="detail">${r.summary||'No issue summary was included in the risk register.'}</p><section><h3>Recommended action</h3><p>${badge(r.planner_action)} ${actionReason(r)}</p></section><section><h3>Explainability panel</h3><p class="detail">Top contributing factors supplied by the Explainability Layer</p>${factors(r).map(x=>`<div class="factor">${x}</div>`).join('')}</section><section><h3>LLM mitigation recommendation</h3>${rec?`<ul>${rec.approved_recommendations.map(x=>`<li>${x}</li>`).join('')}</ul><p>${rec.rationale}</p><p class="${rec.fallback_used?'fallback':'grounded'}">Grounding: ${ground}</p>`:`<p class="detail">Generate LLM recommendations to see approved mitigation strategies for this item.</p>`}</section>`;$('detailPanel').classList.add('open')}
function error(x){$('notice').textContent=x;$('notice').className='notice show'}async function post(url,body){const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),out=await res.json();if(!res.ok)throw Error(out.error||'Request failed.');return out}async function load(items,name){const out=await post('/api/sprint-summary',{items});data=out.items;$('sourceStatus').textContent=name;$('notice').className='notice';$('generateRecommendations').disabled=false;render()}async function generate(){const b=$('generateRecommendations');b.disabled=true;b.textContent='Generating…';try{data=(await post('/api/llm-recommendations',{items:data})).items;render()}catch(e){error(e.message)}finally{b.disabled=false;b.textContent='Generate LLM recommendations'}}
$('fileInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>load(csv(reader.result),f.name).catch(x=>error(x.message));reader.readAsText(f)};$('generateRecommendations').onclick=generate;$('capacityInput').oninput=render;['bandFilter','actionFilter','sortBy'].forEach(x=>$(x).onchange=render);$('closePanel').onclick=()=>$('detailPanel').classList.remove('open');
